workflows.concurrency:
concurrency:
  group: source-gates-${{ github.ref }}
  # Superseded PR heads cannot qualify the current source; do not queue behind them.
  # Release routing and manual runs keep their existing serialization.
  cancel-in-progress: ${{ github.event_name == 'pull_request' }}

concurrency:
  group: solo-native-de332-${{ inputs.lane || 'first-eight' }}
  cancel-in-progress: false

concurrency:
  group: industrial-features-${{ github.event.pull_request.number }}
  cancel-in-progress: true

concurrency:
  group: company-candidate-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

concurrency:
  group: published-pages-smoke-${{ github.event_name }}-${{ github.ref }}
  cancel-in-progress: false

classification.excerpt:
export function dependenciesOf(body = '') {
  return [
    ...new Set(
      [...String(body).matchAll(/(?:depends on|blocked by)\s+#([1-9][0-9]*)/giu)].map((match) =>
        Number(match[1]),
      ),
    ),
  ].sort((a, b) => a - b);
}

export function classification(_pull, paths) {
  if (!Array.isArray(paths) || !paths.length) throw new Error('Empty changed-path inventory.');
  // Queue admission deliberately does not restrict implementation paths. The
  // exact changed-path inventory remains in the receipt for focused testing;
  // titles, milestones, and labels cannot alter an admitted PR's class.
  return 'maintenance';
}

export function admissionBinding(pull, { workflowRevision, policyDigest, paths }) {
  if (
    !sha(pull.head?.sha) ||
    !sha(pull.base?.sha) ||
    !sha(workflowRevision) ||
    !/^[a-f0-9]{64}$/.test(policyDigest || '')
  )
    throw new Error('Exact admission identities required.');
  return {
    format: 'revealline-admission.v1',
    headSha: pull.head.sha,
    baseSha: pull.base.sha,
    workflowRevision,
    policyDigest,
    classification: classification(pull, paths),
    dependencies: dependenciesOf(pull.body),

changedTestAdmission.excerpt:
const commands = [...categories.flatMap((category) => category.commands)];
if (unknownRuntime.length && !fallbackHandled) commands.push(...map.fallbackCommands);

const deferredTests = [];
for (const changed of paths) {
  if (!changed.endsWith('.test.mjs')) continue;
  if (!/^(game\/test|publishing(?:\/pages-controller)?|scripts)\//u.test(changed)) continue;
  if (
    commands.some(
      (command) =>
        command.command === 'node' &&
        command.args[0] === '--test' &&
        command.args.includes(changed),
    )
  )
    continue;
  if (
    categories.some((category) =>
      category.deferredChangedTestPatterns.some((pattern) => pattern.test(changed)),
    )
  ) {
    deferredTests.push(changed);
    continue;
  }
  commands.push({
    id: `changed-test:${changed}`,
    command: 'node',
    args: ['--test', changed],
  });
}

