nativeJobs.header:
timing:
  # Only reviewed declarations execute; later predecessor holds remain, with no automatic launch.
  if: github.repository == 'mekhovov/revealline' && github.event_name == 'workflow_dispatch' && github.ref == 'refs/heads/main' && inputs.lane == 'timing' && contains(fromJSON('["cold-first30","warm-first30","sentry-latency","long-rail-latency","large-capture-erosion","jammer-steering"]'), inputs.phase)
  name: ${{ inputs.phase }} / ${{ matrix.engine }} / ${{ matrix.repetition }}
  runs-on: ubuntu-24.04

lifecycle:
  # Only reviewed declarations execute; later predecessor holds remain, with no automatic launch.
  if: github.repository == 'mekhovov/revealline' && github.event_name == 'workflow_dispatch' && github.ref == 'refs/heads/main' && inputs.lane == 'lifecycle' && contains(fromJSON('["retry","soak","long29"]'), inputs.phase)
  name: ${{ inputs.phase }} / ${{ matrix.engine }} / ${{ matrix.repetition }}
  runs-on: ubuntu-24.04
